class BankAccount {
  accountNumber: string;
  balance: number;

  constructor(accountNumber: string, initialBalance: number = 0) {
    this.accountNumber = accountNumber;
    this.balance = initialBalance;
  }

  deposit(amount: number): void {
    if (amount <= 0) {
      throw new Error("Deposit amount must be positive");
    }
    this.balance += amount;
  }

  getBalance(): number {
    return this.balance;
  }
}

const myAccount = new BankAccount("ACC-12345", 500);
myAccount.deposit(250);
console.log(`Balance: $${myAccount.getBalance()}`); // Balance: $750

class Employee {
  public name: string;          // Accessible everywhere
  protected salary: number;     // Accessible within this class AND derived subclasses
  private ssn: string;          // Accessible ONLY within this Employee class

  constructor(name: string, salary: number, ssn: string) {
    this.name = name;
    this.salary = salary;
    this.ssn = ssn;
  }
}

class Manager extends Employee {
  public getBonus(): number {
    // Allowed: 'salary' is protected, so subclasses can access it
    return this.salary * 0.2;

    // NOT allowed: 'ssn' is private to Employee
    // return this.ssn; // Compile error!
  }
}

const mgr = new Manager("Diana", 80000, "123-45-6789");
console.log(mgr.name); // Allowed: public
