class DatabaseConnection {
  // Parameter property with readonly: automatically declares and assigns immutable field
  constructor(public readonly connectionString: string, public readonly port: number) {}

  connect(): void {
    console.log(`Connecting to ${this.connectionString} on port ${this.port}`);
  }
}

