abstract class PaymentProcessor {
  // Concrete method shared across all processors
  public logTransaction(amount: number): void {
    console.log(`[AUDIT] Initiating transaction of $${amount}`);
  }

  // Abstract method: MUST be implemented by any concrete subclass
  abstract processPayment(amount: number): boolean;
}

class StripeProcessor extends PaymentProcessor {
  processPayment(amount: number): boolean {
    this.logTransaction(amount);
    console.log(`Charging $${amount} via Stripe API`);
    return true;
  }
}

// const invalid = new PaymentProcessor(); // Error: Cannot create an instance of an abstract class.
const stripe = new StripeProcessor();
stripe.processPayment(150);

interface Printable {
  print(): void;
  pageSize: string;
}

class ReportDocument implements Printable {
  public title: string;
  public pageSize: string;

  constructor(title: string, pageSize: string = "A4") {
    this.title = title;
    this.pageSize = pageSize;
  }

  print(): void {
    console.log(`Printing report '${this.title}' on ${this.pageSize} paper.`);
  }
}

const annualReport = new ReportDocument("Q4 Financials");
annualReport.print();

class TemperatureSensor {
  private _celsius: number = 0;

  // Getter for Celsius
  get celsius(): number {
    return this._celsius;
  }

  // Setter with business logic validation
  set celsius(value: number) {
    if (value < -273.15) {
      throw new Error("Temperature cannot drop below Absolute Zero!");
    }
    this._celsius = value;
  }

  // Computed property getter
  get fahrenheit(): number {
    return (this._celsius * 9 / 5) + 32;
  }
}

const sensor = new TemperatureSensor();
sensor.celsius = 25;
console.log(`Celsius: ${sensor.celsius}°C, Fahrenheit: ${sensor.fahrenheit}°F`);
